    [TestMethod]
    public void CalculateDiscount_NegativeAmount_Throws()
    {
        var calc = new DiscountCalculator();
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => calc.CalculateDiscount(-1m));
    }

    [TestMethod]
    public void CalculateDiscount_ZeroOrder_ReturnsZero()
    {
        var calc = new DiscountCalculator();
        Assert.AreEqual(0m, calc.CalculateDiscount(0m));
    }

    // Boundary: exactly 1000 must get 15%, not 10%
    [TestMethod]
    public void CalculateDiscount_Exactly1000_Returns15Percent()
    {
        var calc = new DiscountCalculator();
        Assert.AreEqual(150m, calc.CalculateDiscount(1000m));
    }

    // Boundary: just below 1000 must get 10%
    [TestMethod]
    public void CalculateDiscount_JustBelow1000_Returns10Percent()
    {
        var calc = new DiscountCalculator();
        Assert.AreEqual(99.9m, calc.CalculateDiscount(999m));
    }

    // Boundary: exactly 500 must get 10%, not 5%
    [TestMethod]
    public void CalculateDiscount_Exactly500_Returns10Percent()
    {
        var calc = new DiscountCalculator();
        Assert.AreEqual(50m, calc.CalculateDiscount(500m));
    }

    // Boundary: just below 500 must get 5%
    [TestMethod]
    public void CalculateDiscount_JustBelow500_Returns5Percent()
    {
        var calc = new DiscountCalculator();
        Assert.AreEqual(24.95m, calc.CalculateDiscount(499m));
    }

    // Boundary: exactly 100 must get 5%, not 0%
    [TestMethod]
    public void CalculateDiscount_Exactly100_Returns5Percent()
    {
        var calc = new DiscountCalculator();
        Assert.AreEqual(5m, calc.CalculateDiscount(100m));
    }

    // Boundary: just below 100 must get 0%
    [TestMethod]
    public void CalculateDiscount_JustBelow100_ReturnsZero()
    {
        var calc = new DiscountCalculator();
        Assert.AreEqual(0m, calc.CalculateDiscount(99m));
    }

    // -- CalculateShipping tests --

    [TestMethod]
    public void CalculateShipping_LargeOrder_FreeShipping()
    {
        var calc = new DiscountCalculator();
        var cost = calc.CalculateShipping(500m, 2.0, false);
        Assert.AreEqual(0m, cost);
    }

    [TestMethod]
    public void CalculateShipping_SmallOrder_ReturnsBaseCost()
    {
        var calc = new DiscountCalculator();
        var cost = calc.CalculateShipping(50m, 2.0, false);
        Assert.AreEqual(6.00m, cost);
    }

    [TestMethod]
    public void CalculateShipping_ZeroWeight_Throws()
    {
        var calc = new DiscountCalculator();
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => calc.CalculateShipping(50m, 0, false));
    }

    [TestMethod]
    public void CalculateShipping_ZeroOrderTotal_Throws()
    {
        var calc = new DiscountCalculator();
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => calc.CalculateShipping(0m, 2.0, false));
    }

    // Boundary: exactly 250 should NOT be free (> 250 required)
    [TestMethod]
    public void CalculateShipping_Exactly250_NotFree()
    {
        var calc = new DiscountCalculator();
        var cost = calc.CalculateShipping(250m, 2.0, false);
        Assert.AreEqual(6.00m, cost);
    }

