        var cost = calc.CalculateShipping(50m, 2.0, false);
        Assert.AreEqual(6.00m, cost);
    }

    [TestMethod]
    public void CalculateShipping_ZeroWeight_Throws()
    {
        var calc = new DiscountCalculator();
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => calc.CalculateShipping(50m, 0, false));
    }

    [TestMethod]
    public void CalculateShipping_ZeroOrderTotal_Throws()
    {
        var calc = new DiscountCalculator();
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => calc.CalculateShipping(0m, 2.0, false));
    }

    // Boundary: exactly 250 should NOT be free (> 250 required)
    [TestMethod]
    public void CalculateShipping_Exactly250_NotFree()
    {
        var calc = new DiscountCalculator();
        var cost = calc.CalculateShipping(250m, 2.0, false);
        Assert.AreEqual(6.00m, cost);
    }

    // Boundary: just above 250 should be free
    [TestMethod]
    public void CalculateShipping_JustAbove250_FreeShipping()
    {
        var calc = new DiscountCalculator();
        var cost = calc.CalculateShipping(250.01m, 2.0, false);
        Assert.AreEqual(0m, cost);
    }

    // Express surcharge: 50% on top of base cost
    [TestMethod]
    public void CalculateShipping_Express_Adds50PercentSurcharge()
    {
        var calc = new DiscountCalculator();
        var cost = calc.CalculateShipping(50m, 2.0, true);
        Assert.AreEqual(9.00m, cost); // (5 + 1) * 1.5 = 9
    }

    // Heavy item fee: weight > 10kg adds 15.00
    [TestMethod]
    public void CalculateShipping_HeavyItem_AddsHeavyFee()
    {
        var calc = new DiscountCalculator();
        var cost = calc.CalculateShipping(50m, 15.0, false);
        // base: 5 + 7.5 = 12.5, + heavy fee 15 = 27.5
        Assert.AreEqual(27.50m, cost);
    }

    // Boundary: exactly 10kg should NOT trigger heavy fee
    [TestMethod]
    public void CalculateShipping_Exactly10kg_NoHeavyFee()
    {
        var calc = new DiscountCalculator();
        var cost = calc.CalculateShipping(50m, 10.0, false);
        Assert.AreEqual(10.00m, cost); // 5 + 5 = 10, no heavy fee
    }

    // Express + heavy combined
    [TestMethod]
    public void CalculateShipping_ExpressAndHeavy_BothApply()
    {
        var calc = new DiscountCalculator();
        var cost = calc.CalculateShipping(50m, 15.0, true);
        // base: 5 + 7.5 = 12.5, + heavy 15 = 27.5, * 1.5 = 41.25
        Assert.AreEqual(41.25m, cost);
    }

    // -- ApplyCoupon tests --

    [TestMethod]
    public void ApplyCoupon_Save10_Applies10Percent()
    {
        var calc = new DiscountCalculator();
        var result = calc.ApplyCoupon(100m, "SAVE10");
        Assert.AreEqual(90m, result);
    }

    [TestMethod]
    public void ApplyCoupon_Save20_Applies20Percent()
    {
        var calc = new DiscountCalculator();
        var result = calc.ApplyCoupon(100m, "SAVE20");
        Assert.AreEqual(80m, result);
    }

    [TestMethod]
    public void ApplyCoupon_Flat5_SubtractsFive()
    {
        var calc = new DiscountCalculator();
        var result = calc.ApplyCoupon(50m, "FLAT5");
        Assert.AreEqual(45m, result);
    }

    [TestMethod]
    public void ApplyCoupon_Flat50_SubtractsFifty()
    {
        var calc = new DiscountCalculator();
        var result = calc.ApplyCoupon(200m, "FLAT50");
        Assert.AreEqual(150m, result);
    }

    // Unknown coupon should apply no discount
    [TestMethod]
    public void ApplyCoupon_UnknownCode_NoDiscount()
    {
        var calc = new DiscountCalculator();
        var result = calc.ApplyCoupon(100m, "BOGUS");
        Assert.AreEqual(100m, result);
    }

    // Coupon is case-insensitive
    [TestMethod]
    public void ApplyCoupon_LowercaseCode_StillApplies()
    {
        var calc = new DiscountCalculator();
        var result = calc.ApplyCoupon(100m, "save10");
        Assert.AreEqual(90m, result);
    }

    // Floor: coupon cannot reduce total below 1.00
    [TestMethod]
    public void ApplyCoupon_DiscountExceedsTotal_FloorAt1()
    {
        var calc = new DiscountCalculator();
        var result = calc.ApplyCoupon(2m, "FLAT50");
        Assert.AreEqual(1.00m, result);
    }

    // Floor boundary: result exactly 1.00 stays at 1.00
    [TestMethod]
    public void ApplyCoupon_ResultExactly1_Returns1()
    {
        var calc = new DiscountCalculator();
        // 51 - 50 = 1.00 exactly
        var result = calc.ApplyCoupon(51m, "FLAT50");
        Assert.AreEqual(1.00m, result);
    }

    [TestMethod]
    public void ApplyCoupon_NullCoupon_Throws()
    {
        var calc = new DiscountCalculator();
        Assert.ThrowsExactly<ArgumentNullException>(
            () => calc.ApplyCoupon(100m, null!));
    }

    [TestMethod]
    public void ApplyCoupon_ZeroTotal_Throws()
    {
        var calc = new DiscountCalculator();
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => calc.ApplyCoupon(0m, "SAVE10"));
    }
}

